//! The `globs2` database: filename patterns mapped to media types.
//!
//! # Format
//!
//! `/usr/share/mime/globs2` is generated by `update-mime-database` and is
//! one record per line:
//!
//! ```text
//! 80:text/html:*.html
//! 60:text/x-python:*.py
//! 50:application/x-perl:*.perl
//! ```
//!
//! `weight:mimetype:pattern`, optionally followed by `:flags` (where `cs`
//! means case-sensitive). Higher weight wins. The same pattern legitimately
//! appears many times at different weights -- on this machine `*.exe` maps
//! to five different types between weight 80 and 10 -- which is precisely
//! why a naive `HashMap<ext, mime>` built by last-write-wins gives wrong
//! answers. We keep the best candidate per pattern by (weight, specificity).
//!
//! # Why not `mime.cache`?
//!
//! The same directory holds `mime.cache`, a pre-built binary index. It is
//! faster to query but is a versioned binary format with big-endian offset
//! tables that we'd have to track across releases; `globs2` is stable,
//! textual, and parsing all ~1400 lines takes microseconds. Text wins.

use crate::glob::GlobPattern;
use crate::mime_type::MimeType;
use std::path::Path;

/// One pattern and the type it implies.
#[derive(Debug, Clone)]
struct GlobRule {
    pattern: GlobPattern,
    mime: MimeType,
    /// Database weight; higher beats lower.
    weight: u32,
}

impl GlobRule {
    /// Parse one `weight:mime:pattern[:flags]` line, or `None` for comments,
    /// blanks, and malformed records.
    ///
    /// Uses `splitn(3)` so a pattern containing a `:` (legal -- it's a
    /// filename glob, and `:` is a valid filename character) survives
    /// intact rather than being truncated at the first colon.
    fn parse(line: &str) -> Option<Self> {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            return None;
        }

        let mut parts = line.splitn(3, ':');
        let weight = parts.next()?.trim().parse::<u32>().ok()?;
        let mime = MimeType::parse(parts.next()?)?;
        let rest = parts.next()?;

        // The optional flags field is appended after the pattern. Only `cs`
        // is defined, so look for exactly that suffix rather than splitting
        // on ':' again and corrupting patterns that contain one.
        let (pattern_str, case_sensitive) = rest
            .strip_suffix(":cs")
            .map_or((rest, false), |stripped| (stripped, true));

        if pattern_str.is_empty() {
            return None;
        }

        Some(Self {
            pattern: GlobPattern::with_case(pattern_str, case_sensitive),
            mime,
            weight,
        })
    }

    /// Ranking key for choosing between two matching rules: higher weight
    /// first, then the longer (more specific) pattern.
    const fn rank(&self) -> (u32, usize) {
        (self.weight, self.pattern.specificity())
    }
}

/// The filename→type database.
#[derive(Debug, Clone, Default)]
pub struct GlobDatabase {
    /// Simple `*.ext` rules, bucketed by extension for O(1) lookup. This is
    /// the path ~95% of real queries take.
    by_suffix: Vec<(String, GlobRule)>,
    /// Everything needing a real wildcard walk. Small (a few dozen rules),
    /// so a linear scan is fine.
    complex: Vec<GlobRule>,
}

impl GlobDatabase {
    /// The standard locations, highest priority first. Mirrors the XDG
    /// data-dir resolution `crates/launcher` uses for `.desktop` files --
    /// same spec, same precedence rules.
    #[must_use]
    pub fn search_paths() -> Vec<std::path::PathBuf> {
        let mut dirs = Vec::new();
        let data_home = std::env::var("XDG_DATA_HOME").unwrap_or_else(|_| {
            let home = std::env::var("HOME").unwrap_or_default();
            format!("{home}/.local/share")
        });
        dirs.push(std::path::PathBuf::from(data_home));
        let data_dirs = std::env::var("XDG_DATA_DIRS")
            .unwrap_or_else(|_| "/usr/local/share:/usr/share".to_owned());
        for dir in data_dirs.split(':').filter(|d| !d.is_empty()) {
            dirs.push(std::path::PathBuf::from(dir));
        }
        dirs.into_iter().map(|d| d.join("mime/globs2")).collect()
    }

    /// Load from the system database, merging every `globs2` found.
    ///
    /// A missing file is not an error: a machine without shared-mime-info
    /// installed should still run the browser, just with weaker type
    /// detection (extension guesses plus content sniffing).
    #[must_use]
    pub fn load() -> Self {
        let mut db = Self::default();
        for path in Self::search_paths() {
            if let Ok(text) = std::fs::read_to_string(&path) {
                db.merge_str(&text);
            }
        }
        db
    }

    /// Parse a `globs2` document, adding its rules to this database.
    pub fn merge_str(&mut self, text: &str) {
        for line in text.lines() {
            if let Some(rule) = GlobRule::parse(line) {
                self.insert(rule);
            }
        }
    }

    /// Build a database from a single `globs2` document.
    #[must_use]
    pub fn from_str_data(text: &str) -> Self {
        let mut db = Self::default();
        db.merge_str(text);
        db
    }

    /// Add a rule, keeping only the best candidate per suffix.
    ///
    /// Deduplicating here rather than at query time means the common
    /// lookup never has to compare weights -- and it keeps the table small
    /// despite the database's many repeated patterns.
    fn insert(&mut self, rule: GlobRule) {
        if let Some(ext) = rule.pattern.suffix() {
            let ext = ext.to_owned();
            if let Some((_, existing)) = self.by_suffix.iter_mut().find(|(e, _)| *e == ext) {
                if rule.rank() > existing.rank() {
                    *existing = rule;
                }
            } else {
                self.by_suffix.push((ext, rule));
            }
        } else {
            self.complex.push(rule);
        }
    }

    /// Number of loaded rules -- lets a caller detect an empty database.
    #[must_use]
    pub const fn len(&self) -> usize {
        self.by_suffix.len() + self.complex.len()
    }

    /// Whether no rules loaded at all.
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Look up a type by file name alone.
    ///
    /// Considers every matching rule -- both the suffix table and the
    /// wildcard rules -- and returns the highest-ranked. Checking both is
    /// what lets `libc.so.6` resolve as a shared library even though
    /// `.6` is not a registered extension.
    #[must_use]
    pub fn lookup(&self, filename: &str) -> Option<MimeType> {
        let mut best: Option<&GlobRule> = None;

        // The suffix table holds one rule per extension, but a name can
        // match several (`.tar.gz` matches both `*.gz` and `*.tar.gz`), so
        // scan for the best rather than stopping at the first hit.
        for (_, rule) in &self.by_suffix {
            if rule.pattern.matches(filename) && best.is_none_or(|b| rule.rank() > b.rank()) {
                best = Some(rule);
            }
        }
        for rule in &self.complex {
            if rule.pattern.matches(filename) && best.is_none_or(|b| rule.rank() > b.rank()) {
                best = Some(rule);
            }
        }

        best.map(|r| r.mime.clone())
    }

    /// Look up by path, using only its final component.
    #[must_use]
    pub fn lookup_path(&self, path: &Path) -> Option<MimeType> {
        path.file_name()
            .and_then(|n| n.to_str())
            .and_then(|n| self.lookup(n))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A miniature database exercising the shapes the real file contains,
    /// including the duplicate-pattern-at-different-weights case.
    const SAMPLE: &str = "\
# This file was automatically generated
80:text/html:*.html
60:text/x-python:*.py
50:application/gzip:*.gz
50:application/x-compressed-tar:*.tar.gz
60:application/x-sharedlib:*.so.[0-9]*
50:video/mpeg:[0-9][0-9][0-9].vdr
80:application/x-doom-wad:*.wad
40:application/vnd.microsoft.portable-executable:*.exe
30:application/x-dosexec:*.exe
20:application/x-ms-ne-executable:*.exe
";

    fn sample() -> GlobDatabase {
        GlobDatabase::from_str_data(SAMPLE)
    }

    #[test]
    fn parses_and_skips_comments() {
        let db = sample();
        assert!(!db.is_empty());
        assert_eq!(
            db.lookup("index.html").map(|m| m.to_string()),
            Some("text/html".to_owned())
        );
    }

    /// The headline correctness case: `*.exe` appears three times at
    /// different weights, and the highest must win regardless of file order.
    #[test]
    fn highest_weight_wins_for_duplicate_patterns() {
        let db = sample();
        assert_eq!(
            db.lookup("game.exe").map(|m| m.to_string()),
            Some("application/vnd.microsoft.portable-executable".to_owned()),
            "weight 40 must beat 30 and 20"
        );
    }

    /// Equal weights are broken by specificity, so the compound extension
    /// wins -- otherwise every tarball would report as plain gzip.
    #[test]
    fn longer_pattern_wins_at_equal_weight() {
        let db = sample();
        assert_eq!(
            db.lookup("archive.tar.gz").map(|m| m.to_string()),
            Some("application/x-compressed-tar".to_owned())
        );
        assert_eq!(
            db.lookup("blob.gz").map(|m| m.to_string()),
            Some("application/gzip".to_owned())
        );
    }

    #[test]
    fn wildcard_rules_are_consulted_too() {
        let db = sample();
        assert_eq!(
            db.lookup("libc.so.6").map(|m| m.to_string()),
            Some("application/x-sharedlib".to_owned())
        );
        assert_eq!(
            db.lookup("042.vdr").map(|m| m.to_string()),
            Some("video/mpeg".to_owned())
        );
    }

    #[test]
    fn extension_lookup_is_case_insensitive() {
        let db = sample();
        assert_eq!(
            db.lookup("INDEX.HTML").map(|m| m.to_string()),
            Some("text/html".to_owned())
        );
    }

    #[test]
    fn unknown_names_return_none() {
        let db = sample();
        assert!(db.lookup("mystery").is_none());
        assert!(db.lookup("file.unheardofext").is_none());
    }

    #[test]
    fn malformed_lines_are_skipped_not_fatal() {
        let db = GlobDatabase::from_str_data(
            "not-a-number:text/plain:*.txt\n\
             80:notamimetype:*.foo\n\
             80:text/plain\n\
             \n\
             80:text/plain:*.txt\n",
        );
        assert_eq!(db.len(), 1, "only the well-formed rule survives");
        assert_eq!(
            db.lookup("notes.txt").map(|m| m.to_string()),
            Some("text/plain".to_owned())
        );
    }

    #[test]
    fn case_sensitive_flag_is_honoured() {
        let db = GlobDatabase::from_str_data("50:text/x-c++src:*.C:cs\n");
        assert_eq!(
            db.lookup("main.C").map(|m| m.to_string()),
            Some("text/x-c++src".to_owned())
        );
        assert!(db.lookup("main.c").is_none(), "cs flag must be respected");
    }

    #[test]
    fn lookup_path_uses_only_the_file_name() {
        let db = sample();
        assert_eq!(
            db.lookup_path(Path::new("/some/deep/dir/page.html"))
                .map(|m| m.to_string()),
            Some("text/html".to_owned())
        );
    }

    /// Guards the `splitn(3)` choice: a `:` inside a pattern is legal and
    /// must not truncate the rule.
    #[test]
    fn patterns_containing_colons_survive() {
        let db = GlobDatabase::from_str_data("50:text/plain:*weird:name\n");
        assert!(db.lookup("somethingweird:name").is_some());
    }

    /// Integration with the real system database, when present. Skipped
    /// rather than failed on machines without shared-mime-info, so the
    /// suite stays green in a minimal container.
    #[test]
    fn real_system_database_resolves_common_types() {
        let db = GlobDatabase::load();
        if db.is_empty() {
            return;
        }
        assert_eq!(
            db.lookup("photo.png").map(|m| m.to_string()),
            Some("image/png".to_owned())
        );
        assert_eq!(
            db.lookup("script.py").map(|m| m.to_string()),
            Some("text/x-python".to_owned())
        );
        // The duplicate-weight case, against real data this time.
        assert!(db.lookup("app.exe").is_some());
    }
}
